object.script:
gun_offset = 3.5
function onTick()
if input.getBool(1) then look_azim = input.getNumber(1) look_pitch = input.getNumber(2)
distance = math.max(input.getNumber(3), gun_offset)
output.setNumber(1, 4 * (look_azim + math.asin(gun_offset * math.sin(look_azim * 2 * math.pi) / distance) / (2 * math.pi))) output.setNumber(2, 4 * (look_pitch + math.asin(gun_offset * math.sin(look_pitch * 2 * math.pi) / distance) / (2 * math.pi))) else output.setNumber(1, 0) output.setNumber(2, 0) end end

function onTick() pitch = input.getNumber(1) altitude = input.getNumber(2)
pitch = pitch * 360 depth = -altitude
output.setNumber(1, pitch) output.setNumber(2, depth) end

function onTick() control_right = input.getBool(1) fire = input.getBool(2)
if control_right then fire_left = false fire_right = fire telemetry_channel = 2 video_channel = 1 else fire_left = fire fire_right = false telemetry_channel = 1 video_channel = 0 end
output.setBool(1, fire_left) output.setBool(2, fire_right) output.setNumber(1, telemetry_channel) output.setNumber(2, video_channel) end
